#include "NodeToEventAdapter.h"
NodeToEventAdapter::NodeToEventAdapter(NodeEventRegistry& r,EventSink& s,RuntimeIntegrationEventIdProvider& i):registry_(r),sink_(s),ids_(i),forwarded_(0U),ignored_(0U),failed_(0U),initialized_(false){}
RuntimeIntegrationResult NodeToEventAdapter::begin(){for(size_t i=0U;i<registry_.size();++i)if(registry_.at(i)==nullptr||!registry_.at(i)->isValid())return RuntimeIntegrationResult::INTERNAL_ERROR;registry_.lock();initialized_=true;return RuntimeIntegrationResult::SUCCESS;}RuntimeIntegrationResult NodeToEventAdapter::finish(RuntimeIntegrationResult r){if(r==RuntimeIntegrationResult::SUCCESS)saturatingIncrement(forwarded_);else if(r==RuntimeIntegrationResult::IGNORED||r==RuntimeIntegrationResult::NO_CHANGE||r==RuntimeIntegrationResult::MAPPING_DISABLED)saturatingIncrement(ignored_);else if(r==RuntimeIntegrationResult::RETRY_LATER||r==RuntimeIntegrationResult::REJECTED||r==RuntimeIntegrationResult::FAILED||r==RuntimeIntegrationResult::INTERNAL_ERROR||r==RuntimeIntegrationResult::INVALID_INPUT)saturatingIncrement(failed_);return r;}bool NodeToEventAdapter::isInitialized()const{return initialized_;}
bool NodeToEventAdapter::signalForState(NodeConnectionState s,NodeEventSignal& out){switch(s){case NodeConnectionState::ONLINE:out=NodeEventSignal::ONLINE;return true;case NodeConnectionState::OFFLINE:out=NodeEventSignal::OFFLINE;return true;case NodeConnectionState::DISABLED:out=NodeEventSignal::DISABLED;return true;case NodeConnectionState::UNKNOWN:case NodeConnectionState::DEGRADED:case NodeConnectionState::COUNT:return false;default:return false;}}
bool NodeToEventAdapter::signalForResult(NodeRuntimeResult r,NodeEventSignal& out){switch(r){case NodeRuntimeResult::SUCCESS:out=NodeEventSignal::SEND_SUCCESS;return true;case NodeRuntimeResult::SINK_REJECTED:out=NodeEventSignal::SINK_REJECTED;return true;case NodeRuntimeResult::INTERNAL_ERROR:out=NodeEventSignal::INTERNAL_ERROR;return true;case NodeRuntimeResult::TIMEOUT:out=NodeEventSignal::OFFLINE;return true;case NodeRuntimeResult::NODE_DISABLED:out=NodeEventSignal::DISABLED;return true;case NodeRuntimeResult::INVALID_ARGUMENT:case NodeRuntimeResult::INVALID_NODE_ID:case NodeRuntimeResult::INVALID_NODE:case NodeRuntimeResult::INVALID_ADDRESS:case NodeRuntimeResult::INVALID_MESSAGE:case NodeRuntimeResult::NODE_NOT_FOUND:case NodeRuntimeResult::NODE_OFFLINE:case NodeRuntimeResult::NODE_BUSY:out=NodeEventSignal::SEND_FAILURE;return true;case NodeRuntimeResult::ACCEPTED:case NodeRuntimeResult::IN_PROGRESS:case NodeRuntimeResult::NO_CHANGE:case NodeRuntimeResult::NOT_INITIALIZED:case NodeRuntimeResult::RETRY_LATER:case NodeRuntimeResult::REGISTRY_FULL:case NodeRuntimeResult::DUPLICATE_NODE_ID:case NodeRuntimeResult::DUPLICATE_NODE_ADDRESS:case NodeRuntimeResult::REGISTRY_LOCKED:case NodeRuntimeResult::COUNT:return false;default:return false;}}
RuntimeIntegrationResult NodeToEventAdapter::emit(NodeId id,NodeEventSignal signal,NodeTimestamp now,NodeRuntimeResult result){const NodeEventMapping* m=registry_.find(signal);if(m==nullptr)return finish(RuntimeIntegrationResult::IGNORED);if(!m->enabled())return finish(RuntimeIntegrationResult::MAPPING_DISABLED);Event e;e.id=ids_.nextEventId();if(e.id==0U)return finish(RuntimeIntegrationResult::INTERNAL_ERROR);e.type=m->eventType();e.severity=m->severity();e.sourceType=EventSourceType::NODE;e.sourceId=id;e.timestampMs=now;e.payload.value1=id;e.payload.value2=static_cast<uint32_t>(result);if(!e.isValid())return finish(RuntimeIntegrationResult::INTERNAL_ERROR);switch(sink_.publish(e)){case EventPublishResult::SUCCESS:return finish(RuntimeIntegrationResult::SUCCESS);case EventPublishResult::QUEUE_FULL:return finish(RuntimeIntegrationResult::RETRY_LATER);case EventPublishResult::INVALID_EVENT:case EventPublishResult::DUPLICATE_EVENT:return finish(RuntimeIntegrationResult::REJECTED);default:return finish(RuntimeIntegrationResult::INTERNAL_ERROR);}}
RuntimeIntegrationResult NodeToEventAdapter::onNodeStateChanged(const NodeRuntimeState& previous,const NodeRuntimeState& current,NodeTimestamp now){if(!initialized_)return finish(RuntimeIntegrationResult::NOT_INITIALIZED);if(!previous.isValid()||!current.isValid()||previous.nodeId()!=current.nodeId())return finish(RuntimeIntegrationResult::INVALID_INPUT);if(previous.connectionState()==current.connectionState())return finish(RuntimeIntegrationResult::NO_CHANGE);NodeEventSignal signal=NodeEventSignal::COUNT;if(!signalForState(current.connectionState(),signal))return finish(RuntimeIntegrationResult::IGNORED);return emit(current.nodeId(),signal,now,current.lastResult());}
RuntimeIntegrationResult NodeToEventAdapter::onNodeResult(NodeId id,NodeRuntimeResult result,NodeTimestamp now){if(!initialized_)return finish(RuntimeIntegrationResult::NOT_INITIALIZED);if(id==INVALID_NODE_ID||!isValidNodeRuntimeResult(result))return finish(RuntimeIntegrationResult::INVALID_INPUT);NodeEventSignal signal=NodeEventSignal::COUNT;if(!signalForResult(result,signal))return finish(RuntimeIntegrationResult::IGNORED);return emit(id,signal,now,result);}
uint32_t NodeToEventAdapter::forwardedCount()const{return forwarded_;}uint32_t NodeToEventAdapter::ignoredCount()const{return ignored_;}uint32_t NodeToEventAdapter::failedCount()const{return failed_;}
